class CustomerAccount {
    private int accountId;
    private String customerName;

    // Private static counter ensures IDs cannot be spoofed or duplicated
    private static int idSequence = 1000;

    public CustomerAccount(String name) {
        this.customerName = name;
        this.accountId = ++idSequence; // 1001, 1002, 1003...
    }

    public int getAccountId() { return accountId; }
    public String getCustomerName() { return customerName; }

    public static int getLastIssuedId() {
        return idSequence;
    }
}

public class Main {
    public static void main(String[] args) {
        CustomerAccount c1 = new CustomerAccount("Amit");
        CustomerAccount c2 = new CustomerAccount("Deepa");
        CustomerAccount c3 = new CustomerAccount("Esha");

        System.out.println(c1.getCustomerName() + " ID: " + c1.getAccountId());
        System.out.println(c2.getCustomerName() + " ID: " + c2.getAccountId());
        System.out.println(c3.getCustomerName() + " ID: " + c3.getAccountId());
        System.out.println("Last issued ID across system: " + CustomerAccount.getLastIssuedId());
    }
}

