class AppConfig {
    public static String defaultCurrency = "USD";
    public static boolean maintenanceMode = false;

    public static void enableMaintenance() {
        maintenanceMode = true;
        System.out.println("SYSTEM ALERT: Maintenance mode engaged. All transactions paused.");
    }
}

class PaymentTransaction {
    private double amount;

    public PaymentTransaction(double amount) {
        this.amount = amount;
    }

    public void process() {
        if (AppConfig.maintenanceMode) {
            System.out.println("Payment rejected: System in maintenance.");
            return;
        }
        System.out.println("Processed payment of " + AppConfig.defaultCurrency + " " + amount);
    }
}

public class Main {
    public static void main(String[] args) {
        PaymentTransaction tx1 = new PaymentTransaction(150.0);
        tx1.process();

        // Toggle global configuration:
        AppConfig.enableMaintenance();

        PaymentTransaction tx2 = new PaymentTransaction(75.0);
        tx2.process(); // Safely paused
    }
}

