class BankBranch {
    private String branchName;
    private double branchCash;
    private static double totalNetworkReserves = 0.0;

    public BankBranch(String name) {
        this.branchName = name;
        this.branchCash = 0.0;
    }

    public void depositBranchCash(double amount) {
        if (amount > 0) {
            branchCash += amount;
            totalNetworkReserves += amount;
        }
    }

    public static double getTotalNetworkReserves() {
        return totalNetworkReserves;
    }
}

public class Main {
    public static void main(String[] args) {
        BankBranch b1 = new BankBranch("Downtown");
        BankBranch b2 = new BankBranch("Airport");
        b1.depositBranchCash(2000.0);
        b2.depositBranchCash(3500.0);
        System.out.println("Total network reserves: $" + BankBranch.getTotalNetworkReserves());
    }
}

