class AutonomousFleet {
    private int vehicleId;
    private String status;

    private static int idSequence = 100;
    private static int availableCount = 0;
    private static int onMissionCount = 0;

    public AutonomousFleet() {
        this.vehicleId = ++idSequence;
        this.status = "AVAILABLE";
        availableCount++;
    }

    public void dispatchVehicle() {
        if ("AVAILABLE".equals(status)) {
            this.status = "DISPATCHED";
            availableCount--;
            onMissionCount++;
        }
    }

    public static int getAvailableCount() { return availableCount; }
    public static int getOnMissionCount() { return onMissionCount; }
}

public class Main {
    public static void main(String[] args) {
        AutonomousFleet v1 = new AutonomousFleet();
        AutonomousFleet v2 = new AutonomousFleet();
        AutonomousFleet v3 = new AutonomousFleet();
        v1.dispatchVehicle();
        System.out.println("Available: " + AutonomousFleet.getAvailableCount() + ", On Mission: " + AutonomousFleet.getOnMissionCount());
    }
}
